  --text-heading: 46px;
  --leading-heading: 1.1;
  --tracking-heading: -1.38px;
  --text-heading-lg: 56px;
  --leading-heading-lg: 1.05;
  --tracking-heading-lg: -2.24px;
  --text-display: 66px;
  --leading-display: 1.1;
